for (name, signature, explanation) in (
    (:CredentialValue, "CredentialValue", "Abstract family of ApiKey, BearerToken and AwsCredentials. Default display is redacted, but explicit fields, accessors and serialization expose secrets."),
    (:ApiKey, "ApiKey(value::AbstractString)", "Wrap a nonempty API key. Construction validates shape, not whether a remote account accepts the key. Printing is redacted; accessing value or serializing the object is not."),
    (:BearerToken, "BearerToken(value::AbstractString; expires_at=nothing)", "Wrap an already acquired bearer token, with an optional parseable expiry timestamp string. This does not refresh it or contact an identity service."),
    (:AwsCredentials, "AwsCredentials(; access_key_id, secret_access_key, session_token=nothing, expires_at=nothing)", "Hold AWS signing credentials and optional token/expiry. Display is redacted. The secret and session token remain readable through their explicit fields and serialization."),
    (:Credential, "Credential", "Legacy union alias for AbstractString, CredentialValue and Function. Client credential handling also accepts callable structs through resolve_credential; the union is not a complete test for callable credentials."),
    (:resolve_credential, "resolve_credential(value_or_callable)", "Normalize a string to ApiKey, validate a CredentialValue, or call a zero-argument provider exactly once and normalize its result. A provider returning another callable is rejected. The callback may perform I/O; static values do not."),
    (:LocalOAuthCredential, "LocalOAuthCredential(access_token, refresh_token, expires_at_ms, account_id)", "Hold a stored OAuth credential. Expiry is milliseconds since the epoch or nothing. This is distinct from BearerToken's timestamp spelling. Display is redacted, while access_token and the explicit fields return sensitive values."),
    (:access_token, "access_token(credential)", "Return the raw secret token from LocalOAuthCredential, ApiKey or BearerToken. This accessor does not refresh credentials. Never include its result in diagnostic logs or public examples."),
    (:account_id, "account_id(credential::LocalOAuthCredential)", "Return an optional stored account ID. It is identity metadata, not proof of authorization."),
    (:has_refresh_token, "has_refresh_token(credential::LocalOAuthCredential)", "Return whether a refresh token is present; this performs no refresh or network call."),
    (:is_expired, "is_expired(credential; now=time())", "Check expiry locally with the implementation's safety margin. now is Unix seconds. ApiKey does not expire through this metadata check. Missing expiry is not a remote validity check."),
    (:default_claude_credentials_path, "default_claude_credentials_path()", "Return the standard Claude Code credentials path under the current home directory, without reading it."),
    (:default_codex_auth_path, "default_codex_auth_path()", "Return the standard Codex auth.json path under the current home directory, without reading it."),
    (:read_claude_code_credential, "read_claude_code_credential(path=default_claude_credentials_path())", "Read a local Claude Code credential as LocalOAuthCredential. Missing, malformed or unusable files raise configuration/authentication errors. This reader does not itself refresh or write credentials."),
    (:read_codex_cli_credential, "read_codex_cli_credential(path=default_codex_auth_path())", "Read a Codex LocalOAuthCredential, including account identity and expiry inferred from the stored token where available. It reads local files; it does not perform login or refresh."),
    (:read_xai_credential, "read_xai_credential(path=nothing; env=ENV)", "Read the declared xAI OAuth store, using the selected/default path policy. Return LocalOAuthCredential; this does not start device login or acquire a new token."),
    (:AuthStep, "AuthStep(kind, detail, state)", "Describe one credential source. state is selected, shadowed, absent or unprobed. Unprobed means acquisition was intentionally not performed, not that the credentials are invalid."),
    (:AuthReport, "AuthReport(provider, steps, configured, settings=Dict{String,String}())", "Hold a secret-safe explanation of configured credential sources. configured can include an unprobed cloud mechanism; it does not prove live authentication succeeds. describe includes settings, so review application-supplied metadata before sharing."),
    (:selected_step, "selected_step(report::AuthReport)", "Return the first selected AuthStep, or nothing. A report can be configured through an unprobed source without containing a selected step."),
    (:explain_auth, "explain_auth(provider; env=nothing, api_keys=Dict(), api_key_providers=String[], claude_credentials_path=nothing, codex_auth_path=nothing, xai_credentials_path=nothing, settings=Dict(), files=nothing, home=nothing)\n    explain_auth(router, model)\n    explain_auth(resolution; kwargs...)", "Explain source selection without acquiring a live provider token or submitting a model request. May inspect local files and environment metadata; files can supply a synthetic file map for offline inspection. Values are withheld, but custom settings may be displayed. A report is not a successful login test."),
    (:ChainContext, "ChainContext(; env=ENV, home=get(env,\"HOME\",homedir()), files=nothing, settings=Dict(), clock=time, http=nothing, command=nothing)", "Supply environment, filesystem fixtures, settings, clock and optional HTTP/command hooks to cloud credential resolution. This is an advanced integration/testing surface. Defaults permit real local reads and declared acquisition mechanisms; never assume a context is sandboxed merely because its display is redacted."),
    (:cloud_credential_provider, "cloud_credential_provider(policy::AccessPolicy, context::ChainContext)", "Create a zero-argument credential provider that snapshots identity settings and caches credentials under a lock. Calling it can read files, execute credential commands or contact identity endpoints; expired credentials are reacquired. A bearer token with no expiry is not retained in the cache."),
    (:explain_cloud, "explain_cloud(provider; env=ENV, api_keys=Dict(), settings=Dict(), files=nothing, home=get(env,\"HOME\",homedir()))", "Return an AuthReport for the declared cloud chain without performing acquisition. Local configuration may be inspected. Sources needing commands/network probes are unprobed, not silently selected as a verified account."),
    (:PKCEPair, "PKCEPair(verifier, challenge)", "Hold an OAuth PKCE verifier and its S256 challenge. Generate fresh pairs with generate_pkce and keep the verifier private."),
    (:generate_pkce, "generate_pkce()", "Generate a random PKCE verifier/challenge pair locally. Uses the random source but performs no login or provider request."),
    (:pkce_challenge, "pkce_challenge(verifier::AbstractString)", "Compute the base64url SHA-256 PKCE challenge for a verifier. This deterministic helper performs no network request."),
    (:DeviceAuthorization, "DeviceAuthorization", "Hold a device-login response: device_code, user_code, verification_uri, verification_uri_complete, expires_in and interval. Obtain from start_xai_device_login; do not fabricate or publicly log active codes."),
    (:start_xai_device_login, "start_xai_device_login()", "Contact xAI's device authorization endpoint and return DeviceAuthorization. It does not complete login or store a credential. Show the verification URL/code only to the user authorizing the account."),
    (:poll_xai_device_login, "poll_xai_device_login(device; clock=()->time_ns()/1e9, sleep_fn=sleep)", "Poll the device token endpoint until approval, denial or expiry, honoring the polling interval and slow-down response. Return LocalOAuthCredential without writing it. This is network I/O; DeviceCodeExpiredError is an AuthError."),
    (:CredentialFileStore, "CredentialFileStore(path)\n    CredentialFileStore()", "Select an LM15 credential store. Constructing the handle performs no write. Mutation operations use a cooperating file lock and atomic private replacement; other tools do not necessarily respect that lock."),
    (:mutate!, "mutate!(f, store::CredentialFileStore, provider)", "Under the store lock, pass a deep copy of the current provider entry (or nothing) to f. Return an object to replace that entry; return nothing to leave it unchanged. Returning nothing does NOT delete an entry. Writes are atomic/private; the callback runs under the lock and should not perform slow unrelated work."),
    (:delete_credential!, "delete_credential!(store::CredentialFileStore, provider)", "Remove a provider's local credential entry under lock, preserving other entries. Return nothing. This changes local storage; it does not revoke the credential remotely."),
    (:write_xai_credential, "write_xai_credential(credential::LocalOAuthCredential, path=default_store_path)", "Write the xAI OAuth entry under lock and return the credential. Preserve other store entries and existing omitted refresh/expiry fields. This writes secrets to disk; it does not perform provider login."),
    (:login, "login(provider; credentials_path=default_store_path, echo=println)", "Run the supported interactive xAI device flow, display instructions through echo, poll for authorization and write the resulting credential. Other providers return UnsupportedFeatureError with their own login/key instructions. Explicitly authorize this network and local-write operation."),
)
    doc = "    " * signature * "\n\n" * explanation
    @eval @doc $doc $name
end
# StaticCredential and ApiKey are the same object; one docstring avoids competing
# alias documentation. The reference lists StaticCredential as an explicit alias.
